mapper.update:
UPDATE meeting_follow_up_scan SET claim_token = #{token}, lease_until = #{leaseUntil},
  attempt_count = attempt_count + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status = 'queued'
  AND attempt_count < max_attempts AND next_attempt_at <= #{now}
  AND (claim_token IS NULL OR lease_until <= #{now})

UPDATE meeting_follow_up_scan SET claim_token = NULL, lease_until = NULL, status = 'completed',
  result_json = #{resultJson}, last_error_code = NULL, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND claim_token = #{token}

UPDATE meeting_follow_up_scan SET claim_token = NULL, lease_until = NULL, next_attempt_at = #{nextAttemptAt},
  last_error_code = #{errorCode}, status = #{status}, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND claim_token = #{token}

UPDATE meeting_follow_up_scan SET claim_token = NULL, lease_until = NULL, status = 'blocked',
  last_error_code = #{errorCode}, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND claim_token = #{token}

UPDATE meeting_follow_up_scan SET status = 'blocked', claim_token = NULL, lease_until = NULL,
  last_error_code = 'CANCELLED', updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND occurrence_id = #{occurrenceId} AND status = 'queued'
